// Generates icons/Sources/SqueakIcons/LucideData.swift from Lucide's SVGs.
//   npx tsx scripts/make-lucide-icons.ts [path/to/lucide/icons]
// The curated list below is the whole set the native apps may use; add a name,
// rerun, commit the generated file. Icons: lucide-static, ISC licence.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const dir = process.argv[2] ?? join(root, ".context/v6/lucide/package/icons");
const out = join(root, "icons/Sources/SqueakIcons/LucideData.swift");

export const CURATED = [
  // mapped from SF Symbols used in macos/ and ios/ (see icons/README.md)
  "settings",
  "phone",
  "pin",
  "arrow-up",
  "circle-x",
  "square-pen",
  "search",
  "clipboard-list",
  "list",
  "link",
  "info",
  "hand",
  "triangle-alert",
  "file-text",
  "chevron-down",
  "chevron-up",
  "check",
  "external-link",
  "git-branch",
  "zap-off",
  "message-square",
  "circle-check",
  "code",
  "history",
  "ellipsis",
  "circle-alert",
  "eye-off",
  "moon",
  "users",
  "align-left",
  "message-square-text",
  "wrench",
  // common extras
  "x",
  "bell",
  "play",
  "pause",
  "clock",
  "terminal",
  "monitor",
  "arrow-left",
  "chevron-right",
  "chevron-left",
  "file-pen",
  "paperclip",
  "refresh-cw",
  "copy",
  "trash-2",
  "shield",
  "keyboard",
  "send",
  "eye",
  "brain",
  "sparkles",
  "loader-circle",
  "plus",
  "minus",
  "circle",
  "square-terminal",
  "inbox",
  "smartphone",
  "gauge",
  "folder",
  "house",
  "layers",
];

const num = (s: string | undefined, d = 0) => (s === undefined ? d : Number(s));
const q = (s: string) => JSON.stringify(s);
const camel = (n: string) => {
  const c = n
    .split("-")
    .map((p, i) => (i ? p[0].toUpperCase() + p.slice(1) : p))
    .join("");
  return /^[0-9]/.test(c) ? "_" + c : c;
};
const swiftReserved = new Set([
  "repeat",
  "import",
  "in",
  "is",
  "as",
  "default",
  "case",
  "switch",
  "class",
  "struct",
  "enum",
  "func",
  "var",
  "let",
  "self",
  "init",
]);
const ident = (n: string) => (swiftReserved.has(camel(n)) ? "`" + camel(n) + "`" : camel(n));
const d = (n: number) => String(Number(n.toFixed(6)));

function parse(svg: string, name: string): string[] {
  const els: string[] = [];
  const re = /<(path|circle|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/?>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(svg))) {
    const attrs: Record<string, string> = {};
    for (const a of m[2].matchAll(/([\w:-]+)\s*=\s*"([^"]*)"/g)) attrs[a[1]] = a[2];
    const pts = () =>
      (attrs.points ?? "")
        .trim()
        .split(/[\s,]+/)
        .map(Number)
        .filter((x) => !Number.isNaN(x));
    switch (m[1]) {
      case "path":
        els.push(`.path(${q(attrs.d)})`);
        break;
      case "circle":
        els.push(`.circle(cx: ${d(num(attrs.cx))}, cy: ${d(num(attrs.cy))}, r: ${d(num(attrs.r))})`);
        break;
      case "ellipse":
        els.push(
          `.ellipse(cx: ${d(num(attrs.cx))}, cy: ${d(num(attrs.cy))}, rx: ${d(num(attrs.rx))}, ry: ${d(num(attrs.ry))})`,
        );
        break;
      case "line":
        els.push(
          `.line(x1: ${d(num(attrs.x1))}, y1: ${d(num(attrs.y1))}, x2: ${d(num(attrs.x2))}, y2: ${d(num(attrs.y2))})`,
        );
        break;
      case "polyline":
        els.push(`.polyline([${pts().map(d).join(", ")}])`);
        break;
      case "polygon":
        els.push(`.polygon([${pts().map(d).join(", ")}])`);
        break;
      case "rect": {
        const rx = attrs.rx ?? attrs.ry,
          ry = attrs.ry ?? attrs.rx;
        els.push(
          `.rect(x: ${d(num(attrs.x))}, y: ${d(num(attrs.y))}, width: ${d(num(attrs.width))}, height: ${d(num(attrs.height))}, rx: ${d(num(rx))}, ry: ${d(num(ry))})`,
        );
        break;
      }
    }
  }
  if (!els.length) throw new Error(`${name}: no drawable elements`);
  return els;
}

const names = [...new Set(CURATED)];
let s = `// GENERATED by scripts/make-lucide-icons.ts from lucide-static (ISC, see LICENSE-lucide.txt).\n// Do not edit; change the curated list in the script and rerun.\n\n`;
s += `public enum LucideName: String, CaseIterable, Sendable {\n`;
for (const n of names) s += `    case ${ident(n)} = ${q(n)}\n`;
s += `}\n\nextension LucideName {\n    /// The icon's drawing on Lucide's 24x24 grid.\n    public var elements: [LucideElement] {\n        switch self {\n`;
for (const n of names) {
  const svg = readFileSync(join(dir, `${n}.svg`), "utf8");
  s += `        case .${ident(n)}: return [\n${parse(svg, n)
    .map((e) => `            ${e},`)
    .join("\n")}\n        ]\n`;
}
s += `        }\n    }\n}\n`;
writeFileSync(out, s);
console.log(`wrote ${names.length} icons to ${out}`);
